#!/usr/bin/env node
/**
 * Numaya token build.
 *
 *   node scripts/tokens.mjs          write generated files
 *   node scripts/tokens.mjs --check  fail if generated files are stale or tokens are invalid
 *
 * Source:  tokens/numaya.tokens.json (DTCG draft format)
 * Outputs: src/design-system/tokens.css  CSS custom properties
 *          src/design-system/tokens.js   resolved manifest for the showcase and tests
 *
 * Naming: primitive.color.blue.500   → --p-color-blue-500
 *         semantic.color.brand.default → --color-brand   ("default" segments are dropped)
 *         component.button.height     → --button-height
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = resolve(ROOT, "tokens/numaya.tokens.json");
const CSS_OUT = resolve(ROOT, "src/design-system/tokens.css");
const JS_OUT = resolve(ROOT, "src/design-system/tokens.js");
const LAYERS = ["primitive", "semantic", "component"];
const TYPES = new Set([
  "color", "dimension", "fontFamily", "fontWeight", "duration", "cubicBezier", "shadow", "number", "other",
]);

export function cssVarName(path) {
  const [layer, ...rest] = path;
  const parts = rest.filter((p) => p !== "default");
  return `--${layer === "primitive" ? "p-" : ""}${parts.join("-")}`;
}

export function collect(tree) {
  const tokens = new Map();
  const walk = (node, path, inheritedType) => {
    const type = node.$type ?? inheritedType;
    if (Object.hasOwn(node, "$value")) {
      tokens.set(path.join("."), {
        path,
        layer: path[0],
        type,
        value: String(node.$value),
        description: node.$description ?? null,
        reducedMotion: node.$extensions?.numaya?.reducedMotion ?? null,
      });
      return;
    }
    for (const [key, child] of Object.entries(node)) {
      if (key.startsWith("$") || typeof child !== "object") continue;
      walk(child, [...path, key], type);
    }
  };
  for (const layer of LAYERS) {
    if (!tree[layer]) throw new Error(`Missing layer "${layer}"`);
    walk(tree[layer], [layer]);
  }
  return tokens;
}

const REF = /\{([^}]+)\}/g;

export function validate(tokens) {
  const errors = [];
  const names = new Map();
  for (const [id, t] of tokens) {
    if (!TYPES.has(t.type)) errors.push(`${id}: unknown or missing $type "${t.type}"`);
    const name = cssVarName(t.path);
    if (names.has(name)) errors.push(`${id}: CSS name ${name} collides with ${names.get(name)}`);
    names.set(name, id);
    for (const [, ref] of t.value.matchAll(REF)) {
      const target = tokens.get(ref);
      if (!target) errors.push(`${id}: unresolved reference {${ref}}`);
      else if (t.layer === "primitive") errors.push(`${id}: primitives must hold raw values`);
      else if (t.layer === "semantic" && target.layer === "component")
        errors.push(`${id}: semantic tokens cannot reference component tokens`);
    }
  }
  return errors;
}

export function resolveValue(tokens, id, seen = []) {
  if (seen.includes(id)) throw new Error(`Reference cycle: ${[...seen, id].join(" → ")}`);
  const t = tokens.get(id);
  return t.value.replace(REF, (_, ref) => resolveValue(tokens, ref, [...seen, id]));
}

function toCss(tokens) {
  const line = (t) => {
    const value = t.value.replace(REF, (_, ref) => `var(${cssVarName(tokens.get(ref).path)})`);
    return `  ${cssVarName(t.path)}: ${value};`;
  };
  const byLayer = (layer) => [...tokens.values()].filter((t) => t.layer === layer).map(line);
  const reduced = [...tokens.values()]
    .filter((t) => t.reducedMotion)
    .map((t) => `    ${cssVarName(t.path)}: ${t.reducedMotion};`);
  return [
    "/* Generated by scripts/tokens.mjs from tokens/numaya.tokens.json. Do not edit. */",
    "",
    ":root {",
    "  /* Primitive: raw values. Not for direct use in component CSS. */",
    ...byLayer("primitive"),
    "",
    "  /* Semantic: the public API. */",
    ...byLayer("semantic"),
    "",
    "  /* Component: explicit reusable needs. */",
    ...byLayer("component"),
    "}",
    "",
    "@media (prefers-reduced-motion: reduce) {",
    "  :root {",
    ...reduced,
    "  }",
    "}",
    "",
  ].join("\n");
}

function toJs(tokens) {
  const manifest = [...tokens.entries()].map(([id, t]) => ({
    id,
    name: cssVarName(t.path),
    layer: t.layer,
    type: t.type,
    value: t.value,
    resolved: resolveValue(tokens, id),
    description: t.description,
    ...(t.reducedMotion ? { reducedMotion: t.reducedMotion } : {}),
  }));
  return [
    "// Generated by scripts/tokens.mjs from tokens/numaya.tokens.json. Do not edit.",
    `export const tokens = ${JSON.stringify(manifest, null, 2)};`,
    "",
    "export const tokenByName = Object.fromEntries(tokens.map((t) => [t.name, t]));",
    "",
  ].join("\n");
}

export function build() {
  const tree = JSON.parse(readFileSync(SOURCE, "utf8"));
  const tokens = collect(tree);
  const errors = validate(tokens);
  if (errors.length) throw new Error(`Invalid tokens:\n  ${errors.join("\n  ")}`);
  for (const id of tokens.keys()) resolveValue(tokens, id);
  return { tokens, css: toCss(tokens), js: toJs(tokens) };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const { tokens, css, js } = build();
    if (process.argv.includes("--check")) {
      const stale = [
        [CSS_OUT, css],
        [JS_OUT, js],
      ].filter(([file, content]) => !existsSync(file) || readFileSync(file, "utf8") !== content);
      if (stale.length) {
        console.error(`Generated tokens are stale: ${stale.map(([f]) => f).join(", ")}\nRun: npm run tokens`);
        process.exit(1);
      }
      console.log(`Tokens OK: ${tokens.size} tokens, generated files up to date.`);
    } else {
      writeFileSync(CSS_OUT, css);
      writeFileSync(JS_OUT, js);
      console.log(`Wrote ${tokens.size} tokens → src/design-system/tokens.{css,js}`);
    }
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}
